mapper.select:
SELECT COUNT(*)
FROM financial_product_bookmark b
         INNER JOIN financial_product p
                    ON p.financial_product_id = b.financial_product_id
WHERE b.member_id = #{memberId}
  AND b.child_id = #{childId}
  AND p.is_active = 1
  AND p.target_owner_type IN ('CHILD', 'BOTH')

    AND p.product_type = #{productType}

SELECT b.financial_product_bookmark_id, b.created_at AS bookmarked_at, p.financial_product_id, p.bank_name, p.external_product_id, p.product_type, p.target_owner_type, p.product_subtype, p.name, p.summary, p.highlight_label, p.display_badges_json, p.curation_reason, p.detail_url, p.product_image_key, p.base_interest_rate, p.max_interest_rate, p.interest_rate_reference, p.min_age, p.max_age, p.min_monthly_amount, p.max_monthly_amount, p.contract_period_months, p.min_contract_period_months, p.max_contract_period_months, p.renewal_description, p.interest_payment_method, p.join_termination_method, p.eligibility_conditions_json, p.deposit_conditions_json, p.preferential_conditions_json, p.additional_benefits_json, p.cautions_json, p.is_active AS active, p.source_base_date, p.updated_at FROM financial_product_bookmark b INNER JOIN financial_product p ON p.financial_product_id = b.financial_product_id WHERE b.member_id = #{memberId} AND b.child_id = #{childId} AND p.is_active = 1 AND p.target_owner_type IN ('CHILD', 'BOTH')
AND p.product_type = #{productType}
ORDER BY b.created_at DESC, b.financial_product_bookmark_id DESC LIMIT #{limit} OFFSET #{offset}
